      "assessment": {
        "nobel_worthiness": "Photonic crystals established that periodic dielectric structures can control light through band-structure physics analogous to electronic solids.",
        "attribution": "Yablonovitch and John supplied foundational concepts, while Joannopoulos made central theoretical and computational contributions.",
        "maturity": "The physics is mature, broadly realized, and foundational across nanophotonics.",
        "uncertainties": [
          "The translation from the original full photonic-band-gap vision to diverse later photonic-crystal applications complicates a single prize citation."
        ]
      }
    }
